-- Blizzard ROW Registration K2: verified sessions that fire under any rule, by bitmask, as run for 9 Nov (10 and 11 Nov: same with dates
-- shifted by 1 / 2 days: base [D0-7d, D0), previous day [D0-1d, D0), replay day [D0, D0+1d)). Slimmed copy of 11_ (unused columns and
-- the clean flag removed) + 13_final_export.sql. Bits as in 13_.
WITH b0 AS (SELECT di_matched_signature_at_session_created ms, COUNT(*) c FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='E8A75615-1CBA-5DFF-8032-D16BCF234E10' AND session_last_timestamp>='2026-11-02 00:00' AND session_last_timestamp<'2026-11-10 06:00' AND session_ts>='2026-11-02 00:00' AND session_ts<'2026-11-09 00:00' AND COALESCE(latest_risk_band,'')<>'High' GROUP BY 1), sh AS (SELECT ms, c/SUM(c) OVER () share FROM b0), pd AS (SELECT COUNT(*) pdn FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='E8A75615-1CBA-5DFF-8032-D16BCF234E10' AND session_last_timestamp>='2026-11-08 00:00' AND session_last_timestamp<'2026-11-10 06:00' AND session_ts>='2026-11-08 00:00' AND session_ts<'2026-11-09 00:00'), a0 AS (SELECT session sid, session_ts ts, di_dictionary_num_matched_at_session_created d, di_matched_signature_at_session_created ms, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb, TIME_SLICE(session_ts,20,'MINUTE') b20 FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='E8A75615-1CBA-5DFF-8032-D16BCF234E10' AND session_last_timestamp>='2026-11-08 23:40' AND session_last_timestamp<'2026-11-10 06:00' AND session_ts>='2026-11-08 23:40' AND session_ts<'2026-11-10 00:00'), bc AS (SELECT b20, COUNT(*) bn FROM a0 GROUP BY 1), a1 AS (SELECT a0.*, COUNT(*) OVER (PARTITION BY a0.b20 ORDER BY ts, sid ROWS UNBOUNDED PRECEDING) + COALESCE(p.bn,0) vol FROM a0 LEFT JOIN bc p ON p.b20 = DATEADD(minute,-20,a0.b20)), a2 AS (SELECT a1.*, COUNT(*) OVER (PARTITION BY TO_DATE(ts) ORDER BY ts, sid ROWS UNBOUNDED PRECEDING) + pd.pdn lvol FROM a1 CROSS JOIN pd WHERE ts>='2026-11-09 00:00'), s1 AS (SELECT a2.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, COALESCE(sh.share,0) share, CASE WHEN d IN (1,3) THEN 1 WHEN d=7 THEN 1.5 ELSE 2 END dfac, CASE WHEN d IN (1,3) THEN 1 WHEN d=7 THEN 2 WHEN d IN (15,31) THEN 4 ELSE 6 END dlt FROM a2 LEFT JOIN sh ON sh.ms=a2.ms WHERE a2.d IS NOT NULL), s2 AS (SELECT s1.*, IFF(x IS NULL AND ms IS NOT NULL AND d>0, 1, 0) elig FROM s1), s3 AS (SELECT s2.*, stb r0, ltb r1, IFF(elig=1 AND stc > GREATEST(11, share*vol*5*dfac),1,0) r3, IFF(elig=1 AND stc > GREATEST(8, share*vol*5*dfac),1,0) r4, IFF(elig=1 AND stc > GREATEST(8, share*vol*10*dfac),1,0) r5, IFF(elig=1 AND stc > GREATEST(5, share*vol*5*dfac),1,0) r6, IFF(elig=1 AND stc > GREATEST(11, share*vol*10*dfac),1,0) r7, IFF(elig=1 AND ltc > GREATEST(LEAST(660,1500), share*lvol*5*dlt),1,0) r8, IFF(elig=1 AND ltc > GREATEST(LEAST(480,1500), share*lvol*5*dlt),1,0) r9 FROM s2) SELECT mask, COUNT(*) n, LISTAGG(LEFT(RIGHT(sid,10),7)||RIGHT(sid,1), ',') ids FROM (SELECT sid, r0+2*r1+4*r3+8*r4+16*r5+32*r6+64*r7+128*r8+256*r9 mask FROM s3 WHERE ver=1) WHERE mask>0 GROUP BY mask ORDER BY n DESC;
